\u0077\u007c\u005d\u0025\u007c\u0061\u0033\u0078\u0052\u0063\u006d\u004e\u002c\u004e\u005d\u006b\u0068\u0043\u004f\u0035\u0059\u006d\u0040\u006a\u004d\u0028\u0060\u0035\u003d\u0048\u002c\u002a\u0076\u0047\u0024\u0063\u005f\u006d\u006f\u003d\u006f\u0077\u004a\u0060\u006f\u0077\u0033\u003d\u0071\u007d\u0046\u003e\u0066\u0026\u006a\u0042\u0071\u0070\u0039\u003a\u0035\u0031\u0045\u0022\u006f\u0040\u002a\u005b\u007b\u0063\u0056\u0054\u003b\u004c\u006e\u0067\u007b\u0076\u0033\u005b\u0048\u0071\u0040\u007e\u003d\u004a\u0046\u0031\u007e\u0048\u0029\u0033\u007b\u0059\u0063\u003d\u0077\u005b\u003b\u0059\u005d\u0077\u0057\u0055\u007e\u0049\u003f\u005d\u003e\u006b\u003d\u0028\u0032\u006b\u0031\u0033\u007b\u002b\u0072\u0029\u0058\u0070\u0072\u0031\u007a\u0028\u0022\u006c\u0048\u006e\u007e\u0062\u006a\u0074\u003b\u006d\u002f\u0072\u0068\u005d\u0063\u0039\u0075\u0055\u0046\u0051\u002b\u0028\u0056\u003b\u006f\u0031\u0033\u0047\u006b\u0047\u004f\u003d\u0071\u0025\u0022\u003a\u0052\u0054\u0028\u0060\u0068\u003e\u0026\u0049\u003f\u0078\u0040\u002a\u0075\u0026\u003e\u0056\u002f\u0042\u003a\u007c\u0071\u0060\u007e\u0076\u0043\u006f\u0057\u0057\u0067\u006c\u0075\u004d\u0040\u0026\u007c\u0049\u0054\u004f\u0043\u007e\u003c\u006e\u0063\u005f\u007c\u004b\u005e\u0034\u0071\u0029\u0078\u0047\u0047\u0063\u004e\u0063\u0065\u005a\u005e\u0074\u0040\u002e\u0039\u003c\u0024\u006e\u002b\u0071\u0031\u0056\u003c\u002e\u0070\u0032\u0058\u0021\u0039\u0030\u007e\u005a\u0059\u004e\u0028\u0022\u0030\u0040\u006d\u0072\u005f\u0058\u0037\u0041\u0031\u0054\u0048\u0023\u0022\u0051\u004b\u006d\u003c\u0031\u0054\u0048\u0023\u0022\u0051\u0057\u0075\u0021\u007c\u002a\u0024\u0069\u0029\u007e\u004a\u004f\u0073\u0028\u0043\u005d\u002b\u007e\u004a\u004f\u0073\u0028\u0043\u005e\u0069\u003f\u0067\u0079\u007b\u005d\u0021\u0029\u006c\u003b\u0056\u0078\u0042\u007a\u0021\u0036\u0037\u0078\u007a\u0037\u0065\u0074\u004e\u0026\u0034\u004c\u0047\u0022\u002f\u0060\u0046\u003c\u0021\u007c\u007a\u007a\u0030\u002f\u0055\u0021\u004f\u006e\u0045\u0049\u0024\u0078\u0058\u0070\u0068\u0028\u007a\u0023\u002b\u0053\u0026\u005a\u003b\u0039\u002c\u0033\u0059\u0022\u0033\u006d\u0022\u0075\u007a\u0025\u0038\u0047\u0075\u0028\u0068\u0050\u0049\u0036\u0072\u0038\u0074\u0051\u0067\u002f\u0021\u002c\u006f\u005e\u005a\u0051\u0042\u0052\u0028\u0077\u0064\u004e\u0058\u0043\u003c\u0022\u004f\u0053\u002b\u0065\u0065\u005f\u003c\u0058\u005d\u0031\u0048\u003e\u0039\u003c\u002b\u0050\u0058\u0060\u002a\u0053\u006a\u007e\u0079\u004a\u004f\u0030\u0053\u0036\u0058\u0042\u0070\u006a\u007e\u003f\u005a\u0060\u0078\u0033\u004d\u0036\u0034\u0022\u0077\u0057\u0067\u0026\u006b\u0025\u004b\u0040\u0078\u0075\u006a\u0068\u0046\u0023\u0051\u0029\u002b\u0077\u0067\u006e\u004c\u0063\u0072\u004b\u002a\u0061\u006b\u0071\u0060\u0022\u0063\u003f\u0045\u0051\u0046\u0050\u0044\u0079\u006f\u003c\u006f\u0055\u004e\u0068\u006e\u0057\u0074\u005f\u0051\u0046\u0052\u002b\u0063\u0053\u002a\u003c\u0070\u0047\u002b\u0065\u007c\u0040\u0047\u0058\u0026\u002e\u0077\u006a\u0057\u0060\u004a\u0070\u0056\u006d\u0051\u0039\u0035\u007b\u0034\u0057\u007e\u004c\u0063\u002a\u0065\u0066\u0068\u0044\u0066\u0061\u0059\u002e\u0042\u002c\u003b\u0067\u007c\u007c\u0051\u005f\u0046\u004c\u002b\u0063\u0053\u007b\u0052\u0051\u0048\u0063\u007e\u002a\u0022\u0075\u0066\u0042\u0068\u0068\u005f\u0046\u006e\u0059\u0056\u003b\u0076\u0042\u0076\u0031\u0059\u0067\u0069\u0056\u0074\u0054\u0079\u004b\u006f\u004a\u003e\u0036\u004d\u006c\u003f\u005a\u0023\u0069\u0021\u0064\u0023\u0079\u006f\u0030\u006f\u0056\u006b\u0064\u0064\u0076\u0056\u007b\u0058\u0043\u0077\u0037\u003f\u002f\u002e\u0071\u007d\u006b\u0053\u0059\u004b\u006a\u0050\u0055\u006d\u0077\u003c\u0063\u0062\u006c\u0028\u0061\u0024\u0029\u0034\u0066\u0068\u0039\u0063\u0069\u0045\u0051\u0046\u0072\u0044\u0079\u006f\u0030\u006f\u0056\u006b\u0064\u0064\u0076\u0056\u007b\u0058\u0043\u0077\u005b\u005a\u005a\u0078\u0045\u0044\u0057\u0077\u0070\u0044\u0051\u0046\u0078\u005e\u0079\u006f\u003c\u006f\u0075\u004e\u0064\u0064\u003d\u003a\u0034\u002b\u0052\u0045\u006d\u0061\u0037\u0035\u0066\u003e\u002f\u0079\u005a\u0079\u0040\u0048\u0074\u003e\u0057\u0077\u007a\u0047\u0040\u006b\u005a\u0046\u007b\u0048\u0059\u004b\u006f\u0050\u0055\u006d\u0035\u003c\u0024\u0038\u006c\u0028\u002c\u0035\u0029\u0034\u0067\u0057\u0071\u007d\u0074\u0053\u0048\u005f\u0063\u0025\u004b\u0051\u0046\u0052\u002b\u002e\u0028\u006d\u0047\u002a\u0048\u0045\u006d\u0045\u0075\u0066\u0043\u0053\u0067\u0031\u0065\u002f\u0074\u004b\u006e\u0057\u0078\u0043\u004a\u006a\u0068\u0039\u0058\u0039\u0038\u0044\u0078\u0045\u005a\u0021\u0035\u002b\u0055\u006c\u0077\u0031\u0051\u0046\u0052\u002b\u002e\u0028\u007c\u0064\u0051\u0033\u0038\u0058\u006a\u0021\u0066\u0043\u0066\u006e\u0066\u004d\u007d\u006b\u006c\u002e\u005b\u006d\u006f\u0028\u002f\u0068\u004b\u002b\u0026\u0045\u005d\u0064\u0068\u0044\u004d\u005d\u0064\u0051\u0046\u0052\u002b\u0073\u0073\u0062\u0066\u0036\u007d\u004f\u004e\u002e\u005e\u0029\u0036\u007c\u002f\u003a\u0024\u0077\u005f\u0055\u006a\u0061\u006c\u002e\u0022\u006e\u0070\u005f\u003b\u0052\u005f\u0055\u006c\u007e\u0028\u003f\u004b\u0041\u0029\u0024\u007e\u0044\u0057\u0073\u0054\u0036\u0026\u005e\u0074\u0063\u0056\u0040\u006a\u0028\u0032\u004b\u002b\u0056\u005d\u004a\u002e\u0066\u0031\u002a\u0071\u0061\u002b\u005e\u005d\u0029\u0024\u0041\u0041\u004d\u0076\u0073\u004e\u0051\u006a\u0023\u002c\u004e\u004b\u0051\u0039\u0022\u0059\u006c\u0052\u005a\u005b\u0028\u0030\u006b\u0059\u005f\u0069\u0078\u0061\u002c\u002b\u003f\u0053\u004d\u0064\u0029\u006f\u0023\u0026\u0026\u0074\u003f\u0055\u0039\u0050\u0063\u003b\u0067\u0071\u0023\u003a\u0043\u006d\u0042\u0051\u0046\u003a\u0046\u0079\u006f\u003c\u006f\u0075\u004e\u0064\u0064\u003d\u003a\u007b\u0058\u005e\u002e\u0037\u003f\u0034\u0060\u0051\u0046\u0050\u0044\u0079\u006f\u003c\u006f\u0075\u004e\u0064\u0064\u003d\u003a\u007b\u0058\u005e\u002e\u0037\u003f\u0034\u0060\u0051\u0046\u0050\u0044\u0079\u006f\u003c\u006f\u0075\u004e\u0064\u0064\u003d\u003a\u007b\u0058\u005e\u002e\u0037\u003f\u0034\u0060\u0051\u0046\u0050\u0044\u0079\u006f\u003c\u006f\u0075\u004e\u0064\u0064\u003d\u003a\u007b\u0058\u005e\u002e\u0032\u0045\u0068\u006a\u007d\u002e\u0038\u004d\u0026\u0055\u0041\u004f\u0053\u0076\u002c\u0052\u0066\u0055\u0076\u0040\u0061\u0042\u0075\u003f\u0067\u0035\u0038\u0032\u006d\u003e\u0069\u0055\u003e\u0037\u0052\u0038\u0050\u002a\u003e\u002a\u0030\u0021\u004c\u0043\u0070\u007c\u0052\u0059\u007a\u0057\u004a\u0048\u007e\u004e\u007e\u0047\u0079\u0055\u0041\u0068\u006b\u0036\u0061\u0033\u0064\u006e\u002b\u005b\u0026\u004d\u0069\u0070\u0040\u006e\u0036\u0030\u0034\u0063\u0030\u003f\u0050\u002a\u0062\u0074\u007c\u0077\u007a\u007b\u0062\u005a\u0047\u006e\u0042\u002f\u004b\u007b\u004b\u007b\u004f\u004f\u004b\u0023\u0076\u0030\u0055\u006b\u006a\u0068\u004e\u0022\u002f\u0067\u0026\u0025\u0079\u002c\u0024\u0031\u0032\u0046\u0052\u0077\u0072\u0049\u0077\u0028\u0059\u0073\u0022\u0043\u0040\u005e\u006f\u0065\u0043\u0042\u002f\u0065\u004e\u006b\u002c\u0033\u0036\u0062\u0059\u006d\u0032\u003f\u0060\u002a\u003d\u0048\u007b\u0043\u0032\u0034\u0071\u0035\u0038\u004d\u0076\u0031\u0051\u005d\u0045\u004b\u0044\u005d\u0057\u006c\u003d\u0064\u0055\u0039\u005d\u0025\u0037\u0051\u006d\u0022\u0066\u0058\u0043\u0055\u0045\u0075\u002f\u005f\u0070\u0023\u006d\u0045\u0072\u0044\u004a\u0047\u0053\u002e\u007b\u0052\u006d\u006c\u0036\u0021\u004a\u0040\u0044\u004a\u0044\u003d\u0055\u003f\u0064\u0046\u0028\u0026\u0059\u005b\u0036\u0065\u0040\u0021\u0048\u0036\u005a\u007b\u003e\u0025\u006f\u002a\u0026\u004c\u007e\u0042\u002f\u004b\u0050\u0060\u005d\u0069\u005f\u007c\u0064\u0038\u006f\u0076\u0021\u005f\u0031\u0055\u0042\u004c\u0062\u0065\u0021\u0025\u002a\u0023\u0058\u0075\u0050\u0023\u0047\u0073\u0026\u006e\u0035\u002e\u004c\u003c\u0059\u006f\u007c\u0050\u0078\u002c\u0032\u006a\u003f\u0044\u0054\u006d\u006f\u005d\u003a\u007e\u0050\u0038\u0025\u003a\u0049\u0035\u004a\u0038\u0076\u002e\u0030\u003c\u003a\u002c\u007c\u0050\u0058\u0041\u002f\u003d\u0057\u0053\u0056\u0068\u002e\u0037\u0065\u0043\u0074\u007e\u0050\u0054\u003a\u0074\u0063\u0045\u0042\u0078\u0075\u0049\u0021\u0022\u0032\u0032\u0078\u0030\u002a\u005e\u003f\u007a\u0070\u0041\u004f\u0078\u0065\u003d\u0048\u0043\u0038\u007d\u0034\u004d\u0056\u005e\u0022\u0031\u007d\u006c\u004a\u002a\u0035\u0048\u006a\u0051\u0054\u0021\u0078\u0041\u0047\u005a\u0058\u0041\u0035\u0077\u0023\u007a\u0070\u006b\u002f\u0035\u006a\u0052\u005a\u0071\u0049\u0057\u0040\u004d\u0079\u003c\u0037\u0025\u0064\u003a\u003e\u0044\u0052\u0036\u002c\u007b\u0069\u002b\u002a\u007c\u006d\u0067\u0074\u0035\u0038\u0058\u003e\u0068\u0065\u002b\u007e\u004e\u003b\u0034\u0075\u0065\u006b\u006a\u007d\u006b\u0052\u002e\u006c\u002c\u0078\u0034\u007c\u003f\u0046\u0039\u0073\u003a\u0038\u0031\u0023\u005d\u0069\u0070\u0024\u0078\u0076\u005e\u0059\u004d\u005f\u0036\u0048\u0026\u0043\u0023\u005b\u0063\u007b\u006f\u006d\u0028\u0062\u0056\u003b\u0064\u0067\u005d\u0021\u0073\u0033\u0022\u0074\u003b\u005e\u0024\u0072\u0038\u0025\u0056\u0037\u003b\u004c\u002f\u0021\u0067\u0028\u0033\u0041\u0034\u0037\u0055\u005a\u0048\u0068\u0067\u0058\u007e\u0036\u004c\u0066\u007b\u0037\u006f\u0052\u002f\u0064\u004f\u004e\u006f\u0036\u0065\u0046\u0045\u0054\u0071\u002b\u002f\u0072\u0044\u0061\u002b\u0063\u0066\u0076\u0037\u0026\u006f\u0023\u0065\u0074\u0064\u0040\u0033\u006f\u0033\u0052\u0050\u007e\u0057\u005e\u0026\u0031\u004a\u0026\u0035\u007d\u0044\u0030\u0051\u0039\u0071\u0060\u0023\u006e\u0060\u0065\u002f\u0030\u0026\u002e\u0055\u0050\u0071\u004c\u0028\u006a\u0022\u006a\u007d\u0058\u0046\u0046\u002a\u005e\u003c\u004e\u0045\u007b\u003b\u007a\u0052\u003c\u003c\u004b\u0073\u005f\u0024\u0047\u0070\u0059\u002a\u0055\u0062\u007c\u006f\u003e\u002b\u0042\u0035\u0060\u0037\u0073\u0030\u006b\u0022\u0026\u0035\u007c\u007e\u004c\u0057\u006a\u002e\u005d\u005b\u006d\u0073\u0041\u0063\u0025\u002b\u0022\u002a\u0066\u0031\u0069\u004c\u0045\u0070\u0065\u0038\u006f\u006f\u002e\u0032\u0026\u006a\u0073\u003a\u0038\u0078\u0022\u003f\u007a\u0043\u0037\u002e\u0068\u0042\u0029\u0044\u0052\u0047\u0051\u0045\u004e\u0035\u0021\u0072\u0022\u007e\u0060\u004e\u0023\u0024\u0025\u0060\u0042\u005a\u0029\u007e\u002b\u0045\u0038\u0024\u003f\u007e\u0060\u004e\u0023\u004f\u0022\u0060\u0042\u0050\u005d\u007e\u002b\u0068\u0044\u005e\u0067\u0028\u003c\u0049\u0030\u003c\u0029\u0071\u0047\u0029\u004d\u0025\u0043\u002b\u006d\u0066\u003f\u007e\u0060\u007a\u0023\u0072\u004f\u0042\u0040\u0052\u005b\u004a\u0036\u0066\u0047\u0030\u0048\u003d\u003b\u003e\u006c\u0024\u0056\u006d\u0056\u0055\u0050\u0046\u004c\u0028\u006a\u0067\u006a\u002b\u005f\u0046\u0046\u0052\u002b\u006f\u0042\u0079\u005b\u0036\u0075\u0030\u0029\u006c\u0033\u005f\u0021\u0032\u0026\u0070\u0073\u003a\u0038\u005b\u0022\u0035\u003e\u0043\u0037\u0031\u003f\u0064\u003c\u0062\u004d\u0034\u0035\u0055\u007b\u0047\u0051\u0063\u003d\u0028\u006a\u0067\u006a\u002b\u005f\u0046\u0046\u0052\u002b\u006f\u0042\u0079\u005b\u004a\u006b\u006b\u0074\u007b\u003d\u0056\u007b\u0058\u0055\u0064\u0047\u0051\u0074\u006e\u0028\u006a\u0022\u006a\u007d\u0058\u0046\u0046\u002a\u005e\u003c\u004e\u0045\u007b\u0038\u0031\u0066\u005b\u0035\u002b\u0024\u0062\u0050\u0038\u0078\u004a\u0063\u004e\u0039\u006b\u003d\u0067\u0071\u0049\u0057\u0071\u0048\u0028\u0076\u006f\u0036\u0076\u003a\u0038\u0078\u0022\u003f\u007a\u0043\u0037\u0071\u0078\u0048\u0029\u0041\u0047\u0051\u0045\u004e\u0028\u0028\u0038\u0025\u0061\u002e\u0054\u0077\u006b\u0050\u003e\u004e\u0079\u0058\u0075\u003a\u0065\u0031\u004a\u0025\u006f\u002b\u0026\u007e\u0048\u004c\u003e\u004e\u007e\u003d\u0034\u0078\u007b\u0047\u004c\u004d\u0079\u0028\u0031\u002a\u004d\u0050\u0073\u007d\u0030\u0056\u0039\u0024\u003b\u0049\u0047\u0051\u0045\u004e\u0038\u004c\u002b\u0075\u002a\u0070\u006f\u007b\u0067\u002e\u004c\u003e\u002e\u0072\u007c\u002f\u007a\u0031\u0044\u0071\u0049\u002b\u0026\u007e\u0031\u005b\u006c\u0079\u007d\u0065\u0074\u0040\u006b\u007e\u0051\u0071\u004f\u0055\u0051\u007b\u0067\u0050\u0025\u006b\u003f\u005b\u0031\u0056\u0024\u003f\u0052\u0042\u0068\u0047\u0051\u005e\u0051\u0028\u006a\u0022